f::LocalSpec spec(unsigned ratio=2){f::LocalSpec s;s.owner="smoke";s.source=1;s.originFine={-3,-5,1};s.dimensions={7,5,3};s.finePerWorld=ratio;s.channels={{0,f::ProjectionReduction::VolumeAverage},{1,f::ProjectionReduction::Maximum}};return s;}
e::Emitter emitter(){e::Emitter out;out.id="local_field_input";out.lifeMin=out.lifeMax=240;out.shape=e::Shape::Box;e::Module init;init.vector={0,0,0};init.color={1,1,1,1};init.size={.1f,.1f};out.modules={init};out.renderers.push_back({"sprite","test.png","","",e::Blend::Additive,false});return out;}
